const dbg=false; //debug for Motions

// =========================================================================
// KONFIGURÁCIÓ A BEMUTATÓHOZ (Könnyen átírható értékek)
// =========================================================================
const DEMO_CONFIG = {
    // Button "single" alapértelmezett narancs világítási kép
    button_single: {
        ch1_pct: 0,
        ch2_pct: 0,
        ch3_pct: 0,
        rgb: "FF6B09"
    },
    // Motion "true" esetén aktiválódó bemutató kép (zöld + 92%)
    motion_active: {
        ch1_pct: 0,
        ch2_pct: 0,
        ch3_pct: 92,      // 92% a 3-as (Nagy) csatornára
        rgb: "5CEB0F"     // Zöld szín
    }
};

// Globális és flow állapot inicializálása
if (!global.lampValues) {
    global.lampValues = {
        ch1_raw: 0,    // 0 - 255
        ch2_raw: 0,
        ch3_raw: 0,
        rgb: "000000", // RRGGBB HEX
        status: "OFF"
    };
}

let topic = (msg.topic || "").trim().toLowerCase();
let val = msg.payload;

let fromNextion = false;
let isOff = false;
let isFullSyncNeeded = false; // Ha több csatorna egyszerre változik (pl. gomb, mozgás)
let changedTarget = null;

function clamp(n, min, max) {
    return Math.min(max, Math.max(min, Number(n) || 0));
}

function toHex2(num) {
    return clamp(num, 0, 255).toString(16).padStart(2, '0').toUpperCase();
}

function pctToRaw(pct) {
    return Math.round((clamp(pct, 0, 100) / 100) * 255);
}

// =========================================================================
// 1. BEJÖVŐ ÜZENETEK FELDOLGOZÁSA
// =========================================================================

// --- A) BUTTON (single / double) ---
if (topic === "button" || topic.includes("btn") || topic.includes("zigbee2mqtt")) {
    let action = (typeof val === "object" && val !== null && val.action) ? val.action : String(val);
    action = action.toLowerCase().trim();

    if (action === "single") {
        global.lampValues.ch1_raw = pctToRaw(DEMO_CONFIG.button_single.ch1_pct);
        global.lampValues.ch2_raw = pctToRaw(DEMO_CONFIG.button_single.ch2_pct);
        global.lampValues.ch3_raw = pctToRaw(DEMO_CONFIG.button_single.ch3_pct);
        global.lampValues.rgb = DEMO_CONFIG.button_single.rgb.toUpperCase();
        global.lampValues.status = "ON";
        isFullSyncNeeded = true;
    } else if (action === "double") {
        isOff = true;
        global.lampValues.ch1_raw = 0;
        global.lampValues.ch2_raw = 0;
        global.lampValues.ch3_raw = 0;
        global.lampValues.rgb = "000000";
        global.lampValues.status = "OFF";
    }
}

// --- B) MOTION (true / false) ---
else if (topic === "motion" || topic.includes("motion") || topic.includes("occupancy")) {
    // 1. Logikai állapot kinyerése
    let motionActive = null;
    if (typeof val === "boolean") {
        motionActive = val;
    } else if (typeof val === "string") {
        let s = val.toLowerCase().trim();
        motionActive = (s === "true" || s === "1" || s === "on");
    } else if (typeof val === "number") {
        motionActive = (val === 1);
    } else if (typeof val === "object" && val !== null && val.occupancy !== undefined) {
        motionActive = (val.occupancy === true);
    }
    if(dbg) {
        node.warn(`[MOTION TRIGGER] Beérkezett érték: ${val} -> Értelmezve: ${motionActive}`);
    }

    if (motionActive === true) {
        // Mentés készítése a visszatéréshez
        let currentSnapshot = {
            ch1_raw: global.lampValues.ch1_raw || 0,
            ch2_raw: global.lampValues.ch2_raw || 0,
            ch3_raw: global.lampValues.ch3_raw || 0,
            rgb: global.lampValues.rgb || "000000"
        };

        // Csak akkor mentünk, ha nincs még aktív mentés
        if (!flow.get('motion_saved_state')) {
            flow.set('motion_saved_state', currentSnapshot);
            if(dbg) {
                node.warn(`[MOTION] Állapot elmentve: CH3=${currentSnapshot.ch3_raw}, RGB=${currentSnapshot.rgb}`);
            }
        }

        // Zöld demó beállítása: Nagy lámpa (CH3) 92% -> 235 nyers érték, RGB: 5CEB0F
        global.lampValues.ch1_raw = 0;
        global.lampValues.ch2_raw = 0;
        global.lampValues.ch3_raw = Math.round((92 / 100) * 255); // 235 (hex: EB)
        global.lampValues.rgb = "5CEB0F";
        global.lampValues.status = "ON";

        isFullSyncNeeded = true;
        if(dbg) {
            node.warn(`[MOTION ACTIVE] Zöld beállítva: CH3=235, RGB=5CEB0F`);
        }
    } 
    else if (motionActive === false) {
        let saved = flow.get('motion_saved_state');
        if (saved) {
            global.lampValues.ch1_raw = saved.ch1_raw;
            global.lampValues.ch2_raw = saved.ch2_raw;
            global.lampValues.ch3_raw = saved.ch3_raw;
            global.lampValues.rgb = saved.rgb;
            flow.set('motion_saved_state', null); // Mentés törlése
            if(dbg) {
                node.warn(`[MOTION RESTORE] Eredeti állapot visszaállítva: CH3=${saved.ch3_raw}, RGB=${saved.rgb}`);
            }
        } else {
            if(dbg) {
                node.warn(`[MOTION RESTORE] Nem volt mentett állapot, nem módosítunk.`);
            }
        }
        isFullSyncNeeded = true;
    }
}

// --- C) DASHBOARD OFF GOMB ---
else if (topic === "off") {
    isOff = true;
    global.lampValues.ch1_raw = 0;
    global.lampValues.ch2_raw = 0;
    global.lampValues.ch3_raw = 0;
    global.lampValues.rgb = "000000";
    global.lampValues.status = "OFF";
    context.set('savedState', null);
}

// --- D) NEXTION FELŐL ÉRKEZETT CSOMAG (GetNextionMsg) ---
else if (val && typeof val === "object" && val.domain === "LIGHT") {
    fromNextion = true;

    if (val.target === "CH1" || val.channel === 1) {
        global.lampValues.ch1_raw = clamp(val.value, 0, 255);
        changedTarget = "slider1";
    } else if (val.target === "CH2" || val.channel === 2) {
        global.lampValues.ch2_raw = clamp(val.value, 0, 255);
        changedTarget = "slider2";
    } else if (val.target === "CH3" || val.channel === 3) {
        global.lampValues.ch3_raw = clamp(val.value, 0, 255);
        changedTarget = "slider3";
    } else if (val.target === "RGB") {
        let r = toHex2(val.r);
        let g = toHex2(val.g);
        let b = toHex2(val.b);
        global.lampValues.rgb = `${r}${g}${b}`;
        changedTarget = "rgb";
    }
}

// --- E) DASHBOARD CSÚSZKÁK (0-100%) ---
else if (topic === "slider1") {
    global.lampValues.ch1_raw = pctToRaw(val);
} else if (topic === "slider2") {
    global.lampValues.ch2_raw = pctToRaw(val);
} else if (topic === "slider3") {
    global.lampValues.ch3_raw = pctToRaw(val);
}

// --- F) DASHBOARD SZÍN ÉS GYORSGOMBOK (HEX RRGGBB) ---
else if (topic === "rgb") {
    let s = String(val).trim();
    if (s.startsWith('#')) s = s.slice(1);
    if (/^[0-9A-Fa-f]{6}$/.test(s)) {
        global.lampValues.rgb = s.toUpperCase();
        changedTarget = "rgb";
    } else {
        return null;
    }
} else {
    return null;
}

// Százalékos értékek kalkulációja
let ch1_pct = Math.round((global.lampValues.ch1_raw / 255) * 100);
let ch2_pct = Math.round((global.lampValues.ch2_raw / 255) * 100);
let ch3_pct = Math.round((global.lampValues.ch3_raw / 255) * 100);

// =========================================================================
// 2. KIMENET 1: TCP CSOMAG (#1...)
// =========================================================================
let tcpPacket = `#1${toHex2(global.lampValues.ch1_raw)}${toHex2(global.lampValues.ch2_raw)}${toHex2(global.lampValues.ch3_raw)}${global.lampValues.rgb}\n`;
let tcpMsg = { topic: "home/light/tcp", payload: tcpPacket };

let out1 = tcpMsg;
let out2 = null; // Slider 1
let out3 = null; // Slider 2
let out4 = null; // Slider 3
let out5 = null; // RGB
let out6 = null; // Nextion

// Lekapcsoláskor minden felület nullázása
if (isOff) {
    out2 = { payload: 0 };
    out3 = { payload: 0 };
    out4 = { payload: 0 };
    out5 = { payload: "#000000" };
}
// Teljes kép szinkronizálása (gomb vagy mozgásérzékelő eseményekor)
else if (isFullSyncNeeded) {
    out2 = { payload: ch1_pct };
    out3 = { payload: ch2_pct };
    out4 = { payload: ch3_pct };
    out5 = { payload: `#${global.lampValues.rgb.toLowerCase()}` };
}
// Nextion állításkor csak az érintett csúszka küldése
else if (fromNextion) {
    if (changedTarget === "slider1") out2 = { payload: ch1_pct };
    if (changedTarget === "slider2") out3 = { payload: ch2_pct };
    if (changedTarget === "slider3") out4 = { payload: ch3_pct };
    if (changedTarget === "rgb")     out5 = { payload: `#${global.lampValues.rgb.toLowerCase()}` };
}
// Gyorsgomb megnyomásakor csak a színkarika frissítése
else if (changedTarget === "rgb") {
    out5 = { payload: `#${global.lampValues.rgb.toLowerCase()}` };
}

// =========================================================================
// 3. KIMENET 6: NEXTION MEGJELENÍTÉS (ha NEM Nextionról jött az adat)
// =========================================================================
if (!fromNextion) {
    let dR = parseInt(global.lampValues.rgb.substr(0, 2), 16) || 0;
    let dG = parseInt(global.lampValues.rgb.substr(2, 2), 16) || 0;
    let dB = parseInt(global.lampValues.rgb.substr(4, 2), 16) || 0;

    let nextionCmds = [
        `p[1].h0.val=${dR}`,
        `p[1].n0.val=${dR}`,
        `p[1].h1.val=${dG}`,
        `p[1].n1.val=${dG}`,
        `p[1].h2.val=${dB}`,
        `p[1].n2.val=${dB}`,
        `p[1].h3.val=${global.lampValues.ch1_raw}`,
        `p[1].h4.val=${global.lampValues.ch2_raw}`,
        `p[1].h5.val=${global.lampValues.ch3_raw}`,
        `p[1].n3.val=${ch1_pct}`,
        `p[1].n4.val=${ch2_pct}`,
        `p[1].n5.val=${ch3_pct}`
    ];

    let buffers = [];
    let term = Buffer.from([0xFF, 0xFF, 0xFF]);
    for (let cmd of nextionCmds) {
        buffers.push(Buffer.from(cmd, 'ascii'));
        buffers.push(term);
    }
    out6 = { payload: Buffer.concat(buffers) };
}

// Dupla kiküldés lekapcsolásnál a biztos vételhez
if (tcpPacket === "#1000000000000\n") {
    node.send([out1, out2, out3, out4, out5, out6]);
    setTimeout(() => {
        node.send([out1, null, null, null, null, null]);
    }, 200);
} else {
    node.send([out1, out2, out3, out4, out5, out6]);
}

return null;

var out = msg.payload.substring(2);
msg.payload = null;
if(out.substring(0,6)!="000000") msg.payload = 5;
if(out.substring(6,12)!="000000") msg.payload += 5;
