msg.topic="button";
let input=msg.payload;
msg.payload=input.action;
return msg;

let input = msg.payload.battery;
msg.payload=input;
return msg;

let input = msg.payload.linkquality;
msg.payload=input;
return msg;

if (msg.payload && msg.payload.occupancy !== undefined) {
    msg.topic = "motion";
    msg.payload = (msg.payload.occupancy === true);
    return msg;
}
return null;

let input = msg.payload.battery;
msg.payload=input;
return msg;

let input = msg.payload.linkquality;
msg.payload=input;
return msg;

msg.topic="Win1";
if(msg.payload.contact!=undefined) {
    let input_con = msg.payload.contact;   //normaly true -> door is close
    //node.warn("Door1 c:" + input_con);
    if(input_con === false) {
        node.warn("Alarm!: Door1 - open!");
        msg.payload=true;
        //for mirror
        flow.set('door', 'open');
    } else {
        msg.payload=false;
        //for mirror
        flow.set('door', 'close');
    }
    return msg;
} else {
    //not required object 
}

// Elővesszük a meglevő nyitott kapcsolatot
const session = flow.get("active_tcp_session");

if (!session) {
    node.warn("Nincs aktív TCP kapcsolat az eszköz felé!");
    //return null;
}

// Hozzárendeljük a kimenő parancshoz a nyitott socketet
msg._session = session;

// A kiküldendő parancs (biztosítva a záró 0x0D / \r karaktert)
msg.payload = "?\n";

return msg;

if (msg._session) {
    flow.set("active_tcp_session", msg._session);
}
// Bejövő üzenet szövegesítése, \r (0x0D), \n és felesleges szóközök takarítása
let raw = msg.payload.toString().replace(/[\r\n]+/g, "").trim();

// <TAG>ÉRTÉK</TAG> párok illesztése
const regex = /<([^>]+)>([^<]*)<\/\1>/g;
let parsed = {};
let match;

while ((match = regex.exec(raw)) !== null) {
    let key = match[1];
    let val = match[2];

    // Szöveges azonosítók és állapotok megőrzése, csak a tényleges metrikák számmá konvertálása
    const textKeys = ["ID", "RFID", "OS"];
    if (!textKeys.includes(key) && !isNaN(val) && val !== "") {
        parsed[key] = Number(val);
    } else {
        parsed[key] = val;
    }
}

// 1. RFID esemény (2. kimenet)
if (parsed.RFID !== undefined) {
    msg.topic = "event/rfid";
    msg.payload = {
        type: "rfid_event",
        id: parsed.ID,
        rfid: parsed.RFID,
        timestamp: Date.now()
    };
    return [null, msg, null];
}

// 2. Ajtó / Végállás állapot (3. kimenet)
if (parsed.OS !== undefined) {
    const isOpen = parsed.OS.toUpperCase() === "OPEN";
    msg.topic = "event/door_state";
    msg.payload = {
        type: "state_change",
        id: parsed.ID,
        state: parsed.OS.toUpperCase(),
        isOpen: isOpen,
        timestamp: Date.now()
    };
    return [null, null, msg];
}

// 3. Periodikus környezeti telemetria (1. kimenet)
if (parsed["ToC"] !== undefined || parsed["RH%"] !== undefined) {
    msg.topic = "telemetry/sensor";
    msg.payload = {
        type: "telemetry",
        id: parsed.ID,
        temperature: parsed["ToC"] ?? null,
        humidity: parsed["RH%"] ?? null,
        timestamp: Date.now()
    };
    return [msg, null, null];
}

// Egyéb / ismeretlen formátum (1. kimenetre dobva hibakereséshez)
msg.topic = "telemetry/unknown";
msg.payload = parsed;
return [msg, null, null];

let temp=msg.payload.temperature;
msg.payload=temp;
return msg;

let hum=msg.payload.humidity;
msg.payload=hum;
return msg;

let os=msg.payload.isOpen;
msg.payload=os;
return msg;

let rfid=msg.payload.rfid;
msg.payload=rfid;
node.send(msg);
setTimeout(() => {
        msg.payload="";
        node.send(msg);
    }, 2000);

return null;

if(msg.payload===true) {
    msg.payload="O\n";
} else {
    msg=null;
}
return msg;

if(msg.payload!==null) {
    msg.topic="SELECT u.ID, u.Nev1, u.Nev2, u.jog FROM tags t JOIN users u ON t.user_id = u.ID WHERE t.tag = '"+msg.payload+"';";
    return msg;
} else return null;

let jog = msg?.payload?.[0]?.jog;
msg.payload = (jog === 2);
return msg;

msg.topic="UName";
let user = msg?.payload?.[0];

if (user && user.Nev1 && user.Nev2) {
    msg.payload = `${user.Nev1} ${user.Nev2}`.trim();
} else {
    msg.payload = "";
}

return msg;

// Segédfüggvény: Nextion parancs lezárása 3 db 0xFF bájttal
function nex(cmd) {
    return Buffer.concat([
        Buffer.from(cmd, "utf-8"),
        Buffer.from([0xFF, 0xFF, 0xFF])
    ]);
}

let now = new Date();

// 1. Idő (ÓÓ:PP) -> p[0].t_time
let hours = String(now.getHours()).padStart(2, '0');
let minutes = String(now.getMinutes()).padStart(2, '0');
let timeStr = `${hours}:${minutes}`;

// 2. Dátum (ÉÉÉÉ.HH.NN) -> p[0].t_date
let year = now.getFullYear();
let month = String(now.getMonth() + 1).padStart(2, '0');
let day = String(now.getDate()).padStart(2, '0');
let dateStr = `${year}.${month}.${day}`;

// 3. Magyar napnév -> p[0].t_day
const napok = ["Vasárnap", "Hétfő", "Kedd", "Szerda", "Csütörtök", "Péntek", "Szombat"];
let dayStr = napok[now.getDay()];

// 4. Parancsok kiküldése külön csomagokként
node.send({ payload: nex(`p[0].t_time.txt="${timeStr}"`) });
node.send({ payload: nex(`p[0].t_date.txt="${dateStr}"`) });
node.send({ payload: nex(`p[0].t_day.txt="${dayStr}"`) });

return null;

// Bemeneti buffer egységesítése
let buf = null;
if (Buffer.isBuffer(msg.payload)) {
    buf = msg.payload;
} else if (Array.isArray(msg.payload)) {
    buf = Buffer.from(msg.payload);
} else if (typeof msg.payload === "string") {
    buf = Buffer.from(msg.payload, "binary");
} else {
    return null;
}

// 0D 0A záró karakterek levágása a feldolgozáshoz
let endIdx = buf.indexOf(Buffer.from([0x0D, 0x0A]));
let rawBuf = (endIdx !== -1) ? buf.slice(0, endIdx) : buf;
let now = Date.now();

// Segédfüggvény: megkeresi az adott string címkét (átugorva a Nextion 04 fdfdfd return kódjait)
function findTag(tagStr) {
    let tagBuf = Buffer.from(tagStr, "ascii");
    let idx = rawBuf.indexOf(tagBuf);
    if (idx === -1) return null;
    return {
        idx: idx,
        valOffset: idx + tagBuf.length
    };
}

// =========================================================================
// 1. LIGHT DOMAIN (Világítás - RGB, egyedi és összetett CH1..CH3)
// =========================================================================
let lightTag = findTag("LIGHT:");
if (lightTag) {
    let pBuf = rawBuf.slice(lightTag.valOffset);
    let strView = pBuf.toString("latin1");

    // A) Összetett csomag: LIGHT:CH1:..:CH2:..:CH3:.. (Nextion gyorsgombok)
    if (strView.includes("CH1:") && strView.includes("CH2:")) {
        let outputs = [];
        for (let ch = 1; ch <= 3; ch++) {
            let t = `CH${ch}:`;
            let idx = pBuf.indexOf(Buffer.from(t, "ascii"));
            if (idx !== -1 && (idx + t.length + 4) <= pBuf.length) {
                let v = pBuf.readInt32LE(idx + t.length);
                outputs.push({
                    payload: {
                        domain: "LIGHT",
                        timestamp: now,
                        target: `CH${ch}`,
                        channel: ch,
                        value: Math.min(255, Math.max(0, v))
                    }
                });
            }
        }
        if (outputs.length > 0) {
            for (let m of outputs) node.send(m);
            return null;
        }
    }

    // B) RGB csúszkák: LIGHT:R:<4B>:G:<4B>:B:<4B>
    if (strView.startsWith("R:")) {
        let gIdx = pBuf.indexOf(Buffer.from(":G:", "ascii"));
        let bIdx = pBuf.indexOf(Buffer.from(":B:", "ascii"));
        if (gIdx !== -1 && bIdx !== -1 && (bIdx + 3 + 4) <= pBuf.length) {
            let rVal = pBuf.readInt32LE(2); // "R:" után
            let gVal = pBuf.readInt32LE(gIdx + 3);
            let bVal = pBuf.readInt32LE(bIdx + 3);
            msg.payload = {
                domain: "LIGHT",
                timestamp: now,
                target: "RGB",
                r: Math.min(255, Math.max(0, rVal)),
                g: Math.min(255, Math.max(0, gVal)),
                b: Math.min(255, Math.max(0, bVal))
            };
            return msg;
        }
    }

    // C) Egyedi CH1, CH2, CH3 csúszkák: LIGHT:CHx:<4B>
    for (let ch = 1; ch <= 3; ch++) {
        let t = `CH${ch}:`;
        if (strView.startsWith(t) && pBuf.length >= (t.length + 4)) {
            let v = pBuf.readInt32LE(t.length);
            msg.payload = {
                domain: "LIGHT",
                timestamp: now,
                target: `CH${ch}`,
                channel: ch,
                value: Math.min(255, Math.max(0, v))
            };
            return msg;
        }
    }
}

