             c9 * Math.pow(temp, 2) * Math.pow(rh, 2);

    HI = parseFloat(HI.toFixed(1)); //kerekítjük, levágjuk
    msg.payload=HI;
    // Töröljük a context-ből a tárolt értékeket, hogy ne maradjanak meg
    context.set("temphi", undefined);
    context.set("rhhi", undefined);
// Az üzenet továbbítása
    return msg;
} else {
    // Ha még nincs mindkét adat, nem küldünk semmit
    return null;
}

