// 16-irányú égtáj-váltó fokból
function degToCompass(deg) {
    const iranyok = ["É", "ÉÉK", "ÉK", "KÉK", "K", "KKD", "KD", "DKD", 
                     "D", "DNYD", "DNY", "NYDNY", "NY", "NYÉNY", "ÉNY", "ÉÉNY"];
    let idx = Math.round((deg % 360) / 22.5) % 16;
    return iranyok[idx];
}

