// Segédfüggvény: impulzus küldése (LHAZ, GARAGE)
function triggerPulse(outputIndex, targetName) {
    let startMsg = {
        topic: targetName,
        payload: 1,
        target: targetName,
        timestamp: Date.now()
    };

    let outArr = [null, null, null];
    outArr[outputIndex] = startMsg;
    node.send(outArr);

    setTimeout(() => {
        let stopMsg = {
            topic: targetName,
            payload: 0,
            target: targetName,
            timestamp: Date.now()
        };
        let resetArr = [null, null, null];
        resetArr[outputIndex] = stopMsg;
        node.send(resetArr);
    }, pulseDuration);
}

// Célpontok szétválogatása
