    case "LHAZ":
        triggerPulse(0, "LHAZ"); // 1. kimenet: Lakóház kapu (1 mp impulzus)
        break;

    case "GARAGE":
        triggerPulse(1, "GARAGE"); // 2. kimenet: Garázs kapu (1 mp impulzus)
        break;

    case "DOOR":
